(function mountStaffProfile(){
  const storageKey='crm_session_user'; const readUser=()=>{try{return JSON.parse(localStorage.getItem(storageKey)||'{}');}catch(_){return{};}}; const writeUser=(user)=>localStorage.setItem(storageKey,JSON.stringify(user)); const sourceOf=(user)=>user.avatarUrl||user.avatar_url||user.avatar||user.photoUrl||user.photo_url||user.photo||''; const initials=(user)=>String(user.name||user.fullName||user.username||'С').trim().slice(0,1).toUpperCase();
  const renderAvatar=(host,user)=>{if(!host)return;let avatar=host.querySelector('.staff-profile-avatar');if(!avatar){avatar=document.createElement('span');avatar.className='staff-profile-avatar';host.prepend(avatar);}const source=sourceOf(user);avatar.textContent=source?'':initials(user);avatar.style.backgroundImage=source?'url("'+source.replace(/"/g,'')+'")':'';};
  const open=()=>{if(document.querySelector('.staff-profile-modal'))return;const user=readUser();const modal=document.createElement('div');modal.className='staff-profile-modal';modal.innerHTML='<div class="staff-profile-dialog" role="dialog" aria-modal="true" aria-label="Профиль сотрудника"><button type="button" class="staff-profile-close" aria-label="Закрыть">×</button><div class="staff-profile-dialog__heading"><span class="staff-profile-dialog__avatar staff-profile-preview">'+initials(user)+'</span><div><h2>Мой профиль</h2><p>Аватар и рабочие контакты</p></div></div><label class="staff-profile-field">Аватар<input type="file" class="staff-profile-file" accept="image/png,image/jpeg,image/webp"></label><label class="staff-profile-field">Telegram<input type="text" class="staff-profile-telegram" placeholder="@username или https://t.me/username"></label><p class="staff-profile-error" role="alert"></p><div class="staff-profile-actions"><button type="button" class="staff-profile-cancel">Отмена</button><button type="button" class="staff-profile-save">Сохранить</button></div></div>';document.body.append(modal);const preview=modal.querySelector('.staff-profile-preview'),file=modal.querySelector('.staff-profile-file'),telegram=modal.querySelector('.staff-profile-telegram'),error=modal.querySelector('.staff-profile-error');telegram.value=user.telegram||user.telegramUrl||'';const current=sourceOf(user);if(current){preview.textContent='';preview.style.backgroundImage='url("'+current.replace(/"/g,'')+'")';}file.addEventListener('change',()=>{const selected=file.files?.[0];if(!selected)return;if(selected.size>2*1024*1024){error.textContent='Изображение должно быть не больше 2 МБ.';file.value='';return;}const reader=new FileReader();reader.onload=()=>{preview.textContent='';preview.style.backgroundImage='url("'+String(reader.result).replace(/"/g,'')+'")';preview.dataset.source=String(reader.result);};reader.readAsDataURL(selected);});const close=()=>modal.remove();modal.querySelector('.staff-profile-close').addEventListener('click',close);modal.querySelector('.staff-profile-cancel').addEventListener('click',close);modal.addEventListener('click',(event)=>{if(event.target===modal)close();});modal.querySelector('.staff-profile-save').addEventListener('click',()=>{const value=telegram.value.trim();if(value&&!/^(@[A-Za-z0-9_]{5,32}|https:\/\/t\.me\/[A-Za-z0-9_]{5,32}\/?$)/.test(value)){error.textContent='Укажите @username или ссылку https://t.me/username.';return;}const next={...user,telegram:value};if(preview.dataset.source){next.avatarUrl=preview.dataset.source;next.avatar=preview.dataset.source;}writeUser(next);if(typeof window.__syncStaffProfile==='function')window.__syncStaffProfile(user,value,next.avatarUrl||'');renderAvatar(document.querySelector('.user'),next);close();});};
  const mount=()=>{const host=document.querySelector('.user');if(!host||host.dataset.staffProfileReady==='1')return;host.dataset.staffProfileReady='1';host.setAttribute('role','button');host.tabIndex=0;host.title='Открыть профиль';const user=readUser();renderAvatar(host,user);host.addEventListener('click',open);host.addEventListener('keydown',(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open();}});}; mount(); new MutationObserver(mount).observe(document.body,{childList:true,subtree:true});
})();
;(function syncStaffProfileWithServer(){const original=window.fetch;if(typeof original!=='function'||window.__staffProfileSyncWrapped)return;window.__staffProfileSyncWrapped=true;window.__syncStaffProfile=(user,value,avatar)=>{if(!user?.id)return;const headers=typeof window.sessionHeaders==='function'?window.sessionHeaders():{};headers['Content-Type']='application/json';original('/api/staff/'+encodeURIComponent(user.id)+'/profile',{method:'PATCH',headers,body:JSON.stringify({telegram:value,avatarUrl:avatar||undefined})}).catch(()=>{});};})();
